<script setup lang="ts">
const props=defineProps<{kind:'cyclecount'|'adjustment'}>()
const {t}=useI18n(),route=useRoute(),router=useRouter(),staff=useStaffStore(),warehouse=useWarehouseStore(),{bizErrorMessage}=useBizError()
const data=ref<PaginationData|null>(null),loading=ref(false),error=ref(''),keyword=ref(String(route.query.keyword||'')),counts=ref<Record<string,number>>({}),records=ref<Record<number,any>>({})
const statuses=computed(()=>props.kind==='cyclecount'?['all','pending','in_progress','completed']:['all','pending','approved','completed','cancelled'])
const prefix=computed(()=>props.kind==='cyclecount'?'CC':'ADJ')
const active=computed(()=>route.query.is_active==='false'?'cancelled':String(route.query.status||'all')),page=computed(()=>Number(route.query.page)||1)
const tabs=computed(()=>statuses.value.map(key=>({key,label:t('common.status.'+key.replaceAll('_','-')),count:counts.value[key]})))
const filterFor=(status:string)=>status==='cancelled'?{status:undefined,is_active:false}:{status:status==='all'?undefined:status,is_active:true}
const switchTab=(value:any)=>go(filterFor(String(value)))
const adjustmentReasonLabel=(value:unknown)=>String(value||'—')
const go=(patch:Record<string,any>,keepPage=false)=>{const query:Record<string,any>={...route.query,...patch};if(!keepPage)delete query.page;for(const key of Object.keys(query))if(query[key]==null||query[key]===''||query[key]==='all')delete query[key];router.push({query})}
let previousWarehouseScope=String(warehouse.currentWarehouse?.id??useCookie('warehouse_id').value??'')
let generation=0
const load=async()=>{
 const seq=++generation;loading.value=true;error.value='';records.value={};counts.value={}
 const headers=warehouseHeaders(warehouse.currentWarehouse?.id),base={...route.query,warehouse_id:warehouse.currentWarehouse?.id}
 const results=await Promise.all([httpRequest<PaginationData>('/api/warehouse/'+props.kind+'/',{params:{...base,per_page:20,page:page.value},headers,onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}}),...statuses.value.map(status=>httpRequest<PaginationData>('/api/warehouse/'+props.kind+'/',{params:{...base,...filterFor(status),page:1,per_page:1},headers}))])
 if(seq!==generation)return
 data.value=results[0]||null;loading.value=false
 statuses.value.forEach((status,index)=>{const value=results[index+1];if(value)counts.value[status]=value.total})
 if(data.value)await Promise.all(data.value.items.map(async(row:any)=>{const detail=await httpRequest<any>('/api/warehouse/'+props.kind+'/'+row.id,{headers});if(seq===generation&&detail)records.value[row.id]=detail}))
}
const counted=(row:any)=>(records.value[row.id]?.task_details||[]).filter((line:any)=>line.status==='completed'||line.operator_id!=null).length
const variance=(row:any)=>props.kind==='adjustment'?Number(row.total_actual_quantity||0)-Number(row.total_system_quantity||0):(records.value[row.id]?.task_details||[]).filter((line:any)=>line.status==='completed'||line.operator_id!=null).reduce((sum:number,line:any)=>sum+Number(line.difference||0),0)
const columns=computed(()=>props.kind==='cyclecount'?[
 {key:'task',label:t('cyclecount.entity')},{key:'scope',label:t('operations.ui.scope')},{key:'planned',label:t('cyclecount.fields.scheduled-date')},{key:'progress',label:t('operations.ui.progress')},{key:'variance',label:t('operations.ui.variance')},{key:'next',label:t('operations.ui.next'),align:'right' as const}
]:[{key:'task',label:t('adjustment.entity')},{key:'reason',label:t('adjustment.fields.reason')},{key:'scope',label:t('common.fields.items')},{key:'status',label:t('common.fields.status')},{key:'operator',label:t('operations.ui.time-operator')},{key:'next',label:t('operations.ui.next'),align:'right' as const}])
const deleteTask=async(row:any)=>{if(!await wConfirm({title:t('action-results.delete-confirm-title'),message:t('action-results.delete-confirm',{entity:prefix.value+'-'+row.id}),confirmText:t('button.delete'),cancelText:t('button.cancel')}))return;let success=false;await httpRequest('/api/warehouse/'+props.kind+'/'+row.id,{method:'DELETE',headers:warehouseHeaders(row.warehouse_id),onSuccess:()=>success=true,onError:e=>showToast(bizErrorMessage(e),'error')});if(success)await load()}
watch(()=>route.query,()=>{keyword.value=String(route.query.keyword||'');load()});watch(()=>warehouse.currentWarehouse?.id,id=>{const scope=String(id??'');const changed=scope!==previousWarehouseScope;previousWarehouseScope=scope;if(changed&&route.query.page&&Number(route.query.page)!==1)go({page:1});else load()});onMounted(load);onBeforeUnmount(()=>generation++)
useHead({title:()=>t('nav.'+props.kind)})
</script>
<template><div class="w-task-list w-scope"><header><h1>{{t('nav.'+kind)}}</h1><span>{{data?.total}}</span><WButton v-if="staff.hasPermission(kind+'_edit')" class="w-inventory-create" variant="primary" icon="plus" :to="'/'+kind+'/add'">{{t(kind+'.operations.add')}}</WButton></header><WCard flush><WTabs inset :items="tabs" :model-value="active" :label="t('common.fields.status')" @update:model-value="switchTab" /><form class="w-task-filters" @submit.prevent="go({keyword:keyword.trim()})"><WInput v-model="keyword" type="search" :aria-label="t('common.search')" :placeholder="t('common.search-placeholder')" @change="go({keyword:keyword.trim()})"><template #prefix><WIcon name="search" :size="16" /></template></WInput></form><WAlert v-if="error" tone="block" :title="error" /><WTable :rows="data?.items||[]" :columns="columns" :loading="loading" inset><template #cell-task="{row}"><NuxtLink class="w-task-name" :to="'/'+kind+'/detail/'+row.id">{{prefix}}-{{row.id}}</NuxtLink><span class="w-task-sub">{{row.task_name||row.warehouse?.name}}</span></template><template #cell-scope="{row}"><strong>{{row.detail_count}}</strong><span class="w-task-sub">{{row.warehouse?.name}}</span></template><template #cell-planned="{row}">{{row.scheduled_date?$dayjs(row.scheduled_date,'YYYY-MM-DD',row):'—'}}<span class="w-task-sub">{{row.creator?.user_name}}</span></template><template #cell-progress="{row}"><WStatus :tone="row.status==='completed'?'ok':row.status==='in_progress'?'warn':'none'">{{t('common.status.'+row.status.replaceAll('_','-'))}}</WStatus><span v-if="records[row.id]" class="w-task-sub">{{counted(row)}} / {{row.detail_count}}</span><progress v-if="records[row.id]" class="w-count-progress" :value="counted(row)" :max="Math.max(row.detail_count,1)" :aria-label="t('operations.ui.progress')" /></template><template #cell-variance="{row}"><span v-if="records[row.id]&&counted(row)">{{variance(row)>0?'+':''}}{{variance(row)}}</span><span v-else>—</span></template><template #cell-reason="{row}">{{adjustmentReasonLabel(row.adjustment_reason)}}<NuxtLink v-if="row.cyclecount_id" class="w-task-sub" :to="'/cyclecount/detail/'+row.cyclecount_id">CC-{{row.cyclecount_id}}</NuxtLink></template><template #cell-status="{row}"><WStatus :tone="row.is_active===false?'none':row.status==='completed'?'ok':'warn'">{{t('common.status.'+(row.is_active===false?'cancelled':row.status))}}</WStatus></template><template #cell-operator="{row}">{{row.operator?.user_name||row.approver?.user_name||row.creator?.user_name||'—'}}<span class="w-task-sub">{{$dayjs(row.updated_at,'MM/DD HH:mm',row)}}</span></template><template #cell-next="{row}"><div class="w-task-actions"><WButton size="sm" :to="'/'+kind+'/detail/'+row.id">{{t(row.status==='completed'||row.is_active===false?'operations.ui.view':'operations.ui.process')}}</WButton><WButton v-if="row.status==='pending'&&row.is_active!==false&&staff.hasPermission(kind+'_delete')" size="sm" variant="text" icon="trash" icon-only :aria-label="t('button.delete')" @click="deleteTask(row)" /></div></template></WTable><footer><WPagination :page="page" :page-size="20" :total="data?.total" show-total @update:page="value=>go({page:value},true)" /></footer></WCard></div></template>
<style scoped>
.w-task-list{display:flex;flex-direction:column;gap:16px}.w-task-list header{display:flex;flex-wrap:wrap;gap:12px;align-items:baseline}.w-task-list h1{margin:0;font-size:24px;line-height:32px;font-weight:600}.w-task-list header>span{font-size:13px;color:var(--w-text-2)}.w-task-filters{display:flex;padding:12px 20px;border-bottom:1px solid var(--w-line)}.w-task-filters>.w-input{width:360px;max-width:100%}.w-task-list :deep(.w-table){min-width:900px}.w-task-list :deep(.w-table-wrap.is-inset){--w-table-edge:20px}.w-task-list :deep(.w-table th){height:auto;padding-top:10px;padding-bottom:8px;line-height:16px}.w-task-list :deep(.w-table td){padding-top:12px;padding-bottom:12px;vertical-align:top}.w-task-name{display:block;font-size:14px;line-height:20px;font-weight:500;color:var(--w-text-1);text-decoration:none;margin-bottom:4px}.w-task-link{font-size:13px;color:var(--w-link);text-decoration:none}.w-task-sub{display:block;font-size:12px;line-height:18px;color:var(--w-text-3);margin-top:4px}.w-task-progress{display:flex;flex-direction:column;gap:8px;min-width:120px;max-width:180px}.w-task-progress strong{font-size:14px;font-weight:600}.w-task-progress strong span{color:var(--w-text-3);font-weight:400}.w-task-progress progress{width:100%;height:4px;border:0;border-radius:4px;overflow:hidden;background:#EDEFF3}.w-task-progress progress::-webkit-progress-bar{background:#EDEFF3}.w-task-progress progress::-webkit-progress-value{background:#5F1FE6}.w-task-list footer{padding:12px 20px;border-top:1px solid var(--w-border)}
</style>

<style scoped>.w-inventory-create{margin-left:auto}.w-task-actions{display:flex;justify-content:flex-end;gap:4px}.w-count-progress{display:block;width:100px;height:4px;margin-top:6px;border:0;border-radius:4px;overflow:hidden;background:var(--w-line);appearance:none}.w-count-progress::-webkit-progress-bar{background:var(--w-line)}.w-count-progress::-webkit-progress-value{background:var(--w-pri)}.w-count-progress::-moz-progress-bar{background:var(--w-pri)}</style>
